/* ===================== MEASURING UNIT (enum, i18n-safe) =====================
   Mirrors the backend `measuring_unit` enum. These codes are internal only —
   never shown to users directly. Display labels are resolved per-language
   via unitLabel(). No French text is stored anywhere; translation happens
   entirely here in the frontend display layer. */
const MEASURING_UNITS = ['kg','basket','bag','crate','bunch','tuber_count','tin'];
const UNIT_LABELS = {
  kg:          {en:'kg',       fr:'kg'},
  basket:      {en:'Basket',   fr:'Panier'},
  bag:         {en:'Bag',      fr:'Sac'},
  crate:       {en:'Crate',    fr:'Cageot'},
  bunch:       {en:'Bunch',    fr:'Régime'},
  tuber_count: {en:'Tuber',    fr:'Tubercule'},
  tin:         {en:'Tin',      fr:'Boîte'}
};
function unitLabel(code){ const row = UNIT_LABELS[code]; return row ? (row[state.lang]||row.en) : code; }

/* Conversion-factor table (kg-equivalent per 1 unit), per crop — stands in for the
   backend's conversion-factor logic that auto-populates listing_unit_options.
   The farmer still enters exactly one unit + one price; every other unit price
   shown to buyers is calculated from this table, never manually set. */
/* ===================== LOCATIONS (Cameroon regions/cities, shared across signup, checkout, filters) ===================== */
const LOCATIONS = [
  {region:'Centre', cities:['Yaoundé','Obala','Nkolbisson','Mbalmayo']},
  {region:'Littoral', cities:['Douala']},
  {region:'West', cities:['Bafang','Foumbot','Bafoussam']},
  {region:'North West', cities:['Bamenda']},
  {region:'South West', cities:['Buea']}
];
function locationRegionOptions(){ return LOCATIONS.map(r=>`<option value="${r.region}">${r.region}</option>`).join(''); }
function locationCityOptions(region){ const r = LOCATIONS.find(x=>x.region===region) || LOCATIONS[0]; return r.cities.map(c=>`<option value="${c}">${c}</option>`).join(''); }
function updateCityOptionsFor(regionSelId, citySelId){
  const region = document.getElementById(regionSelId).value;
  document.getElementById(citySelId).innerHTML = locationCityOptions(region);
}

const UNIT_CONVERSION = {
  'Tomatoes':                    {kg:1, basket:12, crate:20, bag:50},
  'Cured Garlic Bulbs':          {kg:1, basket:5,  bag:20,   tin:2},
  'Red Dry Onions':              {kg:1, bag:32,    basket:8.5, crate:18},
  'Okro':                        {kg:1, basket:5,  bag:22,   tin:2},
  'Fresh Plantains (Green/Ripe)':{kg:1, bunch:9,   bag:40},
  'Cocoyams':                    {kg:1, bag:24,    tuber_count:0.4, basket:10},
  'Maize':                       {kg:1, bag:100,   crate:25, tin:2.5, basket:15}
};
function computeUnitOptions(p){
  const table = UNIT_CONVERSION[p.name] || {[p.unit]:1};
  const baseFactor = table[p.unit] || 1;
  const pricePerKg = p.price / baseFactor;
  const out = {};
  Object.keys(table).forEach(u=>{ out[u] = Math.round(pricePerKg * table[u] / 10) * 10; });
  out[p.unit] = p.price; // exact farmer-listed price for their own unit, no rounding drift
  return out;
}


