function farmerName(id){ const f=FARMERS.find(x=>x.id===id); return f ? (id===state.phone ? state.name : f.name) : 'Unknown seller'; }
function isCurrentFarmer(id){ return id===state.phone || id===state.backendUserId; }
function farmerVerified(id){ if(id===state.phone) return state.verification.status==='verified'; const f=FARMERS.find(x=>x.id===id); return f ? f.verified : false; }
function farmerAvatar(id){ if(id===state.phone) return state.avatar; const f=FARMERS.find(x=>x.id===id); return f ? f.avatar : null; }
function farmerLocation(id){ if(id===state.phone) return state.location; const f=FARMERS.find(x=>x.id===id); return f ? f.location : ''; }
function productUnitList(p){ return Object.keys(UNIT_CONVERSION[p.name] || {[p.unit]:1}); }
function unitPrice(p, unit){ const opts = computeUnitOptions(p); return opts[unit]!=null ? opts[unit] : p.price; }
const ALL_UNITS = [...new Set(PRODUCTS.flatMap(p=>productUnitList(p)))];

function renderFilters(){
  document.getElementById('catFilters').innerHTML = ['All',...CATEGORIES].map(c=>{
    const val = c==='All' ? '' : c;
    return `<button class="chip-pill${(state.activeCategory||'')===val?' active':''}" onclick="selectCategory('${val}')">${c}</button>`;
  }).join('');
  document.getElementById('unitFilters').innerHTML = ['All',...ALL_UNITS].map(u=>{
    const val = u==='All' ? '' : u;
    const label = u==='All' ? 'All' : unitLabel(u);
    return `<button class="chip-pill unit${(state.activeUnitFilter||'')===val?' active':''}" onclick="selectUnitFilter('${val}')">${label}</button>`;
  }).join('');
  document.getElementById('locationFilters').innerHTML = ['All',...LOCATIONS.map(r=>r.region)].map(r=>{
    const val = r==='All' ? '' : r;
    return `<button class="chip-pill loc${(state.activeLocationFilter||'')===val?' active':''}" onclick="selectLocationFilter('${val}')">${r}</button>`;
  }).join('');
}
function selectCategory(c){ state.activeCategory = c || null; renderFilters(); renderMarketplace(); }
function selectUnitFilter(u){ state.activeUnitFilter = u || null; renderFilters(); renderMarketplace(); }
function selectLocationFilter(r){ state.activeLocationFilter = r || null; renderFilters(); renderMarketplace(); }
function toggleTrendFilter(t){
  state.activeTrendFilter = state.activeTrendFilter===t ? null : t;
  document.querySelectorAll('[data-trend]').forEach(b=>b.classList.toggle('active', b.dataset.trend===state.activeTrendFilter));
  renderMarketplace();
}
function renderMarketplace(){
  const q = (document.getElementById('searchInput')?.value || '').toLowerCase();
  const verifiedOnly = document.getElementById('verifiedOnly')?.checked;
  const sort = document.getElementById('sortSelect')?.value || 'new';
  let items = PRODUCTS.filter(p=>{
    if(p.status!=='live') return false;
    if(q && !(p.name.toLowerCase().includes(q) || p.category.toLowerCase().includes(q) || farmerName(p.farmerId).toLowerCase().includes(q) || farmerLocation(p.farmerId).toLowerCase().includes(q) || productUnitList(p).some(u=>u.includes(q)))) return false;
    if(state.activeCategory && p.category!==state.activeCategory) return false;
    if(state.activeUnitFilter && !productUnitList(p).includes(state.activeUnitFilter)) return false;
    if(state.activeLocationFilter && !farmerLocation(p.farmerId).startsWith(state.activeLocationFilter)) return false;
    if(verifiedOnly && !farmerVerified(p.farmerId)) return false;
    if(state.activeTrendFilter && p.trend!==state.activeTrendFilter) return false;
    return true;
  });
  if(sort==='asc') items = items.slice().sort((a,b)=>a.price-b.price);
  if(sort==='desc') items = items.slice().sort((a,b)=>b.price-a.price);
  if(sort==='rating') items = items.slice().sort((a,b)=>(farmerVerified(b.farmerId)?1:0)-(farmerVerified(a.farmerId)?1:0));

  const grid=document.getElementById('productGrid');
  if(!items.length){ grid.innerHTML = `<div class="empty-state">No produce matches those filters yet. Try clearing a filter.</div>`; return; }
  grid.innerHTML = items.map(p=>{
    const trendPill = p.trend==='down' ? '<span class="mkt-trend-pill down">▼ Price Fall</span>' : p.trend==='up' ? '<span class="mkt-trend-pill up">▲ Price Rise</span>' : '<span class="mkt-trend-pill flat">● Stable</span>';
    const units = productUnitList(p);
    return `<div class="mkt-card" onclick="openProduct(${p.id})">
      <div class="mkt-card-img thumb">
        <div class="mkt-badge-row">
          ${farmerVerified(p.farmerId) ? '<span class="mkt-verified-pill">✓ Verified</span>' : '<span></span>'}
          ${trendPill}
        </div>
        ${thumbHTML(p.image, p.color, false, 'Add photo')}
        ${farmerLocation(p.farmerId) ? `<span class="mkt-loc-tag">📍 ${farmerLocation(p.farmerId)}</span>` : ''}
      </div>
      <div class="mkt-card-body">
        <div class="mkt-card-cat">${p.category.toUpperCase()}</div>
        <div class="mkt-card-title">${p.name}</div>
        <div class="mkt-card-sub" onclick="event.stopPropagation();openFarmerProfile('${p.farmerId}')">By ${farmerName(p.farmerId)} &middot; ${units.length} measuring unit${units.length===1?'':'s'}</div>
        <div class="mkt-card-price">${p.price.toLocaleString()} <span class="p-unit">XAF/${unitLabel(p.unit)}</span></div>
      </div>
    </div>`;
  }).join('');
}

