/* ===================== PRICE PREDICTOR (ZOOM: Day → Month → Year) ===================== */
const PREDICT_CITIES = [
  {id:'yaounde', name:'Yaoundé', mult:1.08},
  {id:'douala', name:'Douala', mult:1.12},
  {id:'bafoussam', name:'Bafoussam', mult:0.92},
  {id:'bamenda', name:'Bamenda', mult:0.97},
  {id:'buea', name:'Buea', mult:1.05}
];
const PREDICT_TODAY = new Date(2026,7,7); // Aug 7, 2026
const MONTH_NAMES = ['January','February','March','April','May','June','July','August','September','October','November','December'];

function seedRand(seedStr){
  let h = 1779033703 ^ seedStr.length;
  for(let i=0;i<seedStr.length;i++){
    h = Math.imul(h ^ seedStr.charCodeAt(i), 3432918353);
    h = h<<13 | h>>>19;
  }
  h = Math.imul(h ^ h>>>16, 2246822507);
  h = Math.imul(h ^ h>>>13, 3266489909);
  h ^= h>>>16;
  return (h>>>0)/4294967296;
}
const CROP_SEASON = {
  'Tomatoes': {peakMonth:8, amp:0.22, reason:'rainy-season transport disruptions from growing areas'},
  'Cured Garlic Bulbs': {peakMonth:12, amp:0.16, reason:'festive-season cooking demand'},
  'Red Dry Onions': {peakMonth:3, amp:0.14, reason:'dry-season storage tightening supply ahead of the next harvest'},
  'Okro': {peakMonth:7, amp:0.18, reason:'a supply gap between plantings'},
  'Fresh Plantains (Green/Ripe)': {peakMonth:9, amp:0.15, reason:'urban demand outpacing supply between harvest cycles'},
  'Cocoyams': {peakMonth:5, amp:0.12, reason:'thin early-season supply'},
  'Maize': {peakMonth:6, amp:0.20, reason:'stocks running low ahead of the next harvest'}
};
function seasonalMultiplier(cropName, month){
  const s = CROP_SEASON[cropName] || {peakMonth:7, amp:0.15};
  const diff = Math.min(Math.abs(month-s.peakMonth), 12-Math.abs(month-s.peakMonth));
  return 1 + s.amp * Math.cos(diff/6*Math.PI);
}
function yearTrendMultiplier(year){ return 1 + (year-2023)*0.045; }
function predictMonthlyPrice(product, cityId, year, month){
  const base = product.price;
  const city = PREDICT_CITIES.find(c=>c.id===cityId) || PREDICT_CITIES[0];
  const seasonal = seasonalMultiplier(product.name, month);
  const trend = yearTrendMultiplier(year);
  const noise = 0.94 + seedRand(`${product.id}-${cityId}-${year}-${month}`)*0.12;
  return Math.max(10, Math.round(base * city.mult * seasonal * trend * noise / 10) * 10);
}
function predictWeeklyPrices(product, cityId, year, month){
  const m = predictMonthlyPrice(product, cityId, year, month);
  return [1,2,3,4].map(w=>{
    const noise = 0.95 + seedRand(`${product.id}-${cityId}-${year}-${month}-w${w}`)*0.10;
    return Math.max(10, Math.round(m*noise/10)*10);
  });
}
function predictDailyPrice(product, cityId, dateObj){
  const year=dateObj.getFullYear(), month=dateObj.getMonth()+1, day=dateObj.getDate();
  const week = Math.min(4, Math.ceil(day/7));
  const weeks = predictWeeklyPrices(product, cityId, year, month);
  const wp = weeks[week-1];
  const noise = 0.97 + seedRand(`${product.id}-${cityId}-${year}-${month}-${day}`)*0.06;
  return Math.max(10, Math.round(wp*noise/10)*10);
}
function predDaysBetween(a,b){ return Math.round((b-a)/86400000); }
function predIsFuture(d){ return predDaysBetween(PREDICT_TODAY, d) > 0; }
function predIsActualMonth(year, month){ return year<2026 || (year===2026 && month<=7); }
function predConfidenceForDate(d){
  const diff = predDaysBetween(PREDICT_TODAY, d);
  if(diff<=0) return 96;
  return Math.max(38, Math.round(96 - diff*0.65));
}
function fmtPredDate(d){ return d.toLocaleDateString('en-GB',{weekday:'long', day:'numeric', month:'long', year:'numeric'}); }
function addDays(d, n){ const r = new Date(d); r.setDate(r.getDate()+n); return r; }

const TIER_RANK = {high:3, medium:2, low:1};
function effectiveTier(p, dateObj){
  if(!predIsFuture(dateObj)) return 'high'; // past/today are actuals, not forecasts — always shown in full
  const conf = predConfidenceForDate(dateObj);
  const dateTier = conf>=70 ? 'high' : conf>=40 ? 'medium' : 'low';
  return TIER_RANK[dateTier] <= TIER_RANK[p.tier] ? dateTier : p.tier;
}
function predDayClickable(dateObj){
  // Past & today are always viewable. Only future dates are capped at 90 days, per the accuracy rule.
  return predDaysBetween(PREDICT_TODAY, dateObj) <= 90;
}
function startOfWeek(d){
  const r = new Date(d); const day = r.getDay();
  r.setDate(r.getDate() + (day===0 ? -6 : 1-day)); // Monday-start week
  return r;
}
function trendIcon(p, dateObj){
  const prev = predictDailyPrice(p, state.predict.cityId, addDays(dateObj,-1));
  const cur = predictDailyPrice(p, state.predict.cityId, dateObj);
  if(cur>prev*1.01) return '▲'; if(cur<prev*0.99) return '▼'; return '●';
}

state.predict = { cropId:null, cityId:'yaounde', currentYear:2026, currentMonth:PREDICT_TODAY.getMonth()+1, currentDay:new Date(PREDICT_TODAY), currentWeekStart:startOfWeek(new Date(PREDICT_TODAY)) };

function predictCropOptions(){
  const available = PRODUCTS.filter(p=>p.status==='live' && p.forecastAvailable);
  if(!available.length) return '<span class="muted">No forecast is available for the current marketplace products.</span>';
  return `<select onchange="predictChangeCrop(this.value)">${available.map(p=>`<option value="${p.id}" ${p.id===state.predict.cropId?'selected':''}>${p.name}</option>`).join('')}</select>`;
}
function predictCityOptions(){
  return `<select onchange="predictChangeCity(this.value)">${PREDICT_CITIES.map(c=>`<option value="${c.id}" ${c.id===state.predict.cityId?'selected':''}>${c.name}</option>`).join('')}</select>`;
}
function predictYearOptions(activeYear){
  return `<select onchange="predictChangeYear(this.value)">${[2023,2024,2025,2026].map(y=>`<option value="${y}" ${y===activeYear?'selected':''}>${y}</option>`).join('')}</select>`;
}
function openPrediction(id){
  const product = PRODUCTS.find(p=>p.id===id);
  if(!product?.forecastAvailable){ toast('No model forecast is available for this product.'); return; }
  state.predict.cropId = id;
  state.currentProductId = id;
  if(!state.predict.cityId) state.predict.cityId = 'yaounde';
  go('prediction');
  renderPredDay(new Date(PREDICT_TODAY));
}
function predictChangeCrop(id){ state.predict.cropId = Number(id); state.currentProductId = Number(id); predictRerenderCurrent(); }
function predictChangeCity(cid){ state.predict.cityId = cid; predictRerenderCurrent(); }
function predictChangeYear(y){ renderPredYear(Number(y)); }
function predictRerenderCurrent(){
  const active = document.querySelector('.pred-screen.active');
  if(!active) return;
  if(active.id==='predDay') renderPredDay(state.predict.currentDay || new Date(PREDICT_TODAY));
  else if(active.id==='predWeek') renderPredWeek(state.predict.currentWeekStart || startOfWeek(new Date(PREDICT_TODAY)));
  else if(active.id==='predMonth') renderPredMonth(state.predict.currentYear, state.predict.currentMonth);
  else renderPredYear(state.predict.currentYear || 2026);
}
function showPredScreen(name){
  const targetId = 'pred'+name;
  ['predDay','predWeek','predMonth','predYear'].forEach(id=>{
    const el = document.getElementById(id);
    el.classList.toggle('active', id===targetId);
    el.style.display = (id===targetId) ? 'block' : 'none';
  });
  document.querySelectorAll('.pred-tabbtn').forEach(b=>b.classList.toggle('active', b.dataset.tab===name.toLowerCase()));
}
function predGoTab(tab){
  if(tab==='day') renderPredDay(state.predict.currentDay || new Date(PREDICT_TODAY));
  else if(tab==='week') renderPredWeek(state.predict.currentWeekStart || startOfWeek(state.predict.currentDay || new Date(PREDICT_TODAY)));
  else if(tab==='month') renderPredMonth(state.predict.currentYear||2026, state.predict.currentMonth||(PREDICT_TODAY.getMonth()+1));
  else renderPredYear(state.predict.currentYear||2026);
}

/* ---------- YEAR VIEW ---------- */
function renderPredYear(year){
  const p = PRODUCTS.find(x=>x.id===state.predict.cropId); if(!p) return;
  state.predict.currentYear = year;
  document.getElementById('predYearFilters').innerHTML = `<label>Crop ${predictCropOptions()}</label><label>City ${predictCityOptions()}</label><label>Year ${predictYearOptions(year)}</label>`;
  document.getElementById('pred-crumb-name').textContent = p.name;
  document.getElementById('predYearTitle').textContent = `${year} Price Forecast for ${p.name} in ${PREDICT_CITIES.find(c=>c.id===state.predict.cityId).name}`;

  const months = [];
  for(let m=1;m<=12;m++) months.push({m, price: predictMonthlyPrice(p, state.predict.cityId, year, m), actual: predIsActualMonth(year,m)});
  let peak = months[0];
  months.forEach(x=>{ if(x.price>peak.price) peak=x; });
  const season = CROP_SEASON[p.name] || {reason:'seasonal demand shifts'};
  document.getElementById('predYearInsight').innerHTML = `📈 <b>Prediction:</b> Prices likely to peak around <b>${MONTH_NAMES[peak.m-1]}</b> due to ${season.reason}.`;
  document.getElementById('predYearChart').innerHTML = svgYearChart(months);
  showPredScreen('Year');
}
function svgYearChart(months){
  const W=680,H=260,padL=48,padR=16,padT=20,padB=34;
  const prices = months.map(x=>x.price);
  const min = Math.min(...prices)*0.9, max = Math.max(...prices)*1.1;
  const xFor = i => padL + i*((W-padL-padR)/11);
  const yFor = v => padT + (H-padT-padB)*(1-(v-min)/(max-min));
  let transitionIdx = months.findIndex(x=>!x.actual);
  if(transitionIdx===-1) transitionIdx = months.length;
  const actualPoly = months.slice(0, transitionIdx).map((x,i)=>`${xFor(i)},${yFor(x.price)}`).join(' ');
  const predPoly = months.slice(Math.max(0,transitionIdx-1)).map((x,i)=>`${xFor(transitionIdx-1+i)},${yFor(x.price)}`).join(' ');
  const dots = months.map((x,i)=>`<circle cx="${xFor(i)}" cy="${yFor(x.price)}" r="5" fill="${x.actual?'#1976D2':'#FB8C00'}" stroke="#fff" stroke-width="1.5" style="cursor:pointer;" onclick="renderPredMonth(${state.predict.currentYear},${x.m})"/>`).join('');
  const labels = months.map((x,i)=>`<text x="${xFor(i)}" y="${H-12}" text-anchor="middle" font-size="10" fill="#757575">${MONTH_NAMES[x.m-1].slice(0,3)}</text>`).join('');
  const gridY = [0,0.25,0.5,0.75,1].map(f=>{
    const val = min + f*(max-min); const y = yFor(val);
    return `<line x1="${padL}" y1="${y}" x2="${W-padR}" y2="${y}" stroke="#F1F5EA" stroke-width="1"/><text x="${padL-8}" y="${y+3}" text-anchor="end" font-size="9" fill="#9AA090">${Math.round(val)}</text>`;
  }).join('');
  return `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto;">${gridY}
    <polyline points="${actualPoly}" fill="none" stroke="#1976D2" stroke-width="2.5"/>
    <polyline points="${predPoly}" fill="none" stroke="#FB8C00" stroke-width="2.5" stroke-dasharray="6 5"/>
    ${dots}${labels}</svg>`;
}
function predYearBack(){ openProduct(state.predict.cropId); }

/* ---------- MONTH VIEW: bar chart + real weekday-aligned calendar ---------- */
function renderPredMonth(year, month){
  const p = PRODUCTS.find(x=>x.id===state.predict.cropId); if(!p) return;
  state.predict.currentYear = year; state.predict.currentMonth = month;
  document.getElementById('predMonthFilters').innerHTML = `<label>Crop ${predictCropOptions()}</label><label>City ${predictCityOptions()}</label>`;
  document.getElementById('pred-crumb-name').textContent = p.name;
  document.getElementById('predMonthTitle').textContent = `${MONTH_NAMES[month-1]} ${year} — ${p.name} Price Prediction`;

  const weeks = predictWeeklyPrices(p, state.predict.cityId, year, month);
  const lo = Math.min(...weeks), hi = Math.max(...weeks);
  document.getElementById('predMonthRange').textContent = `${lo.toLocaleString()} – ${hi.toLocaleString()} FCFA`;
  document.getElementById('predMonthChart').innerHTML = svgMonthBars(weeks);

  const daysInMonth = new Date(year, month, 0).getDate();
  const firstDow = new Date(year, month-1, 1).getDay();
  let anyClickable = false;
  const cells = [];
  for(let i=0;i<firstDow;i++) cells.push(`<div class="pred-cal-cell empty"></div>`);
  for(let d=1; d<=daysInMonth; d++){
    const dt = new Date(year, month-1, d);
    const clickable = predDayClickable(dt);
    const isToday = predDaysBetween(PREDICT_TODAY, dt)===0;
    const isPast = predDaysBetween(PREDICT_TODAY, dt) < 0;
    const price = clickable ? Math.round(predictDailyPrice(p, state.predict.cityId, dt)) : null;
    if(clickable) anyClickable = true;
    cells.push(`<button type="button" class="pred-cal-cell${clickable?' has-value':''}${clickable?'':' disabled'}${isToday?' today':''}${isPast?' past':''}" onclick="predictMonthClickDay(${year},${month},${d})">
      <span class="pred-day-number">${d}</span>
      ${price !== null ? `<span class="pred-day-price">${price.toLocaleString()}</span>` : ''}
    </button>`);
  }
  document.getElementById('predMonthCalendar').innerHTML = cells.join('');
  document.getElementById('predMonthAlert').style.display = anyClickable ? 'none' : 'flex';
  showPredScreen('Month');
}
function svgMonthBars(weeks){
  const W=400,H=200,padL=40,padR=16,padT=16,padB=30;
  const max = Math.max(...weeks)*1.15, min=0;
  const slot=(W-padL-padR)/weeks.length, bw=slot*0.55;
  const bars = weeks.map((v,i)=>{
    const x = padL + i*slot + (slot-bw)/2;
    const h = (H-padT-padB)*(v-min)/(max-min);
    const y = H-padB-h;
    return `<rect x="${x}" y="${y}" width="${bw}" height="${h}" rx="5" fill="#689F38"/>
      <text x="${x+bw/2}" y="${y-6}" text-anchor="middle" font-size="10" fill="#37474F" font-weight="600">${v.toLocaleString()}</text>
      <text x="${x+bw/2}" y="${H-12}" text-anchor="middle" font-size="10" fill="#757575">Wk ${i+1}</text>`;
  }).join('');
  return `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto;">${bars}</svg>`;
}
function predictMonthClickDay(year, month, day){
  const dt = new Date(year, month-1, day);
  if(!predDayClickable(dt)){
    const p = PRODUCTS.find(x=>x.id===state.predict.cropId);
    openPredLimitModal(predictMonthlyPrice(p, state.predict.cityId, year, month));
    return;
  }
  renderPredDay(dt);
}
function openPredLimitModal(avg){
  document.getElementById('predLimitText').textContent = `For accuracy, daily predictions are only available up to 3 months ahead. Here's the monthly average: ${avg.toLocaleString()} FCFA.`;
  document.getElementById('predLimitModal').classList.add('open');
}
function closePredLimitModal(){ document.getElementById('predLimitModal').classList.remove('open'); }
function predMonthBack(){ renderPredYear(state.predict.currentYear || 2026); }

/* ---------- WEEK VIEW: forecast-list style, inspired by weather-app 7/10-day lists ---------- */
function renderPredWeek(weekStart){
  const p = PRODUCTS.find(x=>x.id===state.predict.cropId); if(!p) return;
  state.predict.currentWeekStart = weekStart;
  state.predict.currentYear = weekStart.getFullYear();
  state.predict.currentMonth = weekStart.getMonth()+1;
  document.getElementById('predWeekFilters').innerHTML = `<label>Crop ${predictCropOptions()}</label><label>City ${predictCityOptions()}</label>`;
  document.getElementById('pred-crumb-name').textContent = p.name;
  const weekEnd = addDays(weekStart,6);
  document.getElementById('predWeekTitle').textContent = `Week of ${weekStart.toLocaleDateString('en-GB',{day:'numeric',month:'long'})} – ${weekEnd.toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'})}`;

  const days = [];
  for(let i=0;i<7;i++){
    const d = addDays(weekStart,i);
    days.push({date:d, price: predictDailyPrice(p, state.predict.cityId, d), tier: effectiveTier(p,d)});
  }
  const numeric = days.filter(x=>x.tier!=='low').map(x=>x.price);
  const lo = numeric.length ? Math.min(...numeric) : 0, hi = numeric.length ? Math.max(...numeric) : 1;
  const DOW = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  document.getElementById('predWeekList').innerHTML = days.map(x=>{
    const isToday = predDaysBetween(PREDICT_TODAY, x.date)===0;
    const pct = (x.tier!=='low' && hi>lo) ? Math.round(((x.price-lo)/(hi-lo))*100) : 50;
    const dowLabel = isToday ? 'Today' : DOW[x.date.getDay()];
    const priceLabel = x.tier==='low' ? 'Low confidence' : x.price.toLocaleString()+' FCFA';
    return `<div class="pred-week-row${isToday?' today':''}" onclick="renderPredDay(new Date(${x.date.getFullYear()},${x.date.getMonth()},${x.date.getDate()}))">
      <span class="pwr-day">${dowLabel}<span class="pwr-date">${x.date.getDate()} ${MONTH_NAMES[x.date.getMonth()].slice(0,3)}</span></span>
      <span class="pwr-trend">${trendIcon(p,x.date)}</span>
      <span class="pwr-bar-track">${x.tier!=='low' ? `<span class="pwr-bar-fill" style="width:${pct}%"></span>` : ''}</span>
      <span class="pwr-price">${priceLabel}</span>
    </div>`;
  }).join('');
  showPredScreen('Week');
}
function predWeekBack(){ const d = state.predict.currentWeekStart; renderPredMonth(d.getFullYear(), d.getMonth()+1); }

/* ---------- DAY VIEW: default entry, tiered confidence + always-visible Why panel ---------- */
function renderPredDay(dateObj){
  const p = PRODUCTS.find(x=>x.id===state.predict.cropId); if(!p) return;
  state.predict.currentDay = dateObj;
  state.predict.currentYear = dateObj.getFullYear();
  state.predict.currentMonth = dateObj.getMonth()+1;
  document.getElementById('predDayFilters').innerHTML = `<label>Crop ${predictCropOptions()}</label><label>City ${predictCityOptions()}</label>`;
  document.getElementById('pred-crumb-name').textContent = p.name;
  document.getElementById('predDayTitle').textContent = fmtPredDate(dateObj);

  const tier = effectiveTier(p, dateObj);
  const price = predictDailyPrice(p, state.predict.cityId, dateObj);
  const margin = Math.round(price*0.04/10)*10;
  const conf = predIsFuture(dateObj) ? predConfidenceForDate(dateObj) : 96;
  const box = document.getElementById('predDayValueBox');
  if(tier==='high'){
    box.innerHTML = `<div class="pred-big-num">${price.toLocaleString()} <span>FCFA</span></div><div class="pred-sub-range">± ${margin.toLocaleString()} FCFA</div>`;
  } else if(tier==='medium'){
    const lo=Math.round(price*0.88/10)*10, hi=Math.round(price*1.12/10)*10;
    box.innerHTML = `<div class="pred-big-num pred-big-range">${lo.toLocaleString()}–${hi.toLocaleString()} <span>FCFA</span></div><div class="pred-sub-range">Likely range — no single price shown at this confidence</div>`;
  } else {
    const arrow = p.trend==='down'?'▼':p.trend==='up'?'▲':'●';
    const word = p.trend==='down'?'Falling':p.trend==='up'?'Rising':'Stable';
    box.innerHTML = `<div class="pred-big-direction">${arrow} ${word}</div><div class="pred-sub-range">Low confidence — not enough verified history for a number</div>`;
  }
  const confColor = conf>=70 ? '#43A047' : conf>=40 ? '#B98900' : '#D32F2F';
  document.getElementById('predDayConfLabel').textContent = `Confidence: ${conf}%`;
  document.getElementById('predDayConfBar').style.width = conf+'%';
  document.getElementById('predDayConfBar').style.background = confColor;

  const yest = addDays(dateObj,-1), tom = addDays(dateObj,1);
  const stripDefs = [{label:'Yesterday', d:yest}, {label:predDaysBetween(PREDICT_TODAY,dateObj)===0?'Today':'Selected day', d:dateObj}, {label:'Tomorrow', d:tom}];
  document.getElementById('predDayStrip').innerHTML = stripDefs.map(x=>{
    const t = effectiveTier(p, x.d);
    const pr = predictDailyPrice(p, state.predict.cityId, x.d);
    return `<div class="pred-strip-item"><div class="psi-label">${x.label}</div><div class="psi-icon">${trendIcon(p,x.d)}</div><div class="psi-price">${t==='low' ? '—' : pr.toLocaleString()+' F'}</div></div>`;
  }).join('');

  // Why panel — shown in every confidence tier, per the SRS: confidence changes precision, not whether reasoning is explained.
  document.getElementById('predDayWhySupply').textContent = p.why.supply;
  document.getElementById('predDayWhySeason').textContent = p.why.season;
  document.getElementById('predDayWhyWeather').textContent = p.why.weather;
  document.getElementById('predDayWhyDemand').textContent = p.why.demand;

  const past = predictDailyPrice(p, state.predict.cityId, addDays(dateObj,-7));
  const future = predictDailyPrice(p, state.predict.cityId, addDays(dateObj,7));
  let tip;
  if(tier==='low') tip = `Theraprice Tip: History for this listing is too thin for a confident buy/wait call — check back as more sales come in.`;
  else if(future>past*1.03) tip = `Theraprice Tip: Buy now — price is expected to rise over the next week.`;
  else if(future<past*0.97) tip = `Theraprice Tip: You may want to wait — price is expected to fall over the next week.`;
  else tip = `Theraprice Tip: Prices look stable — a good time to buy at your convenience.`;
  document.getElementById('predDayTip').textContent = tip;
  showPredScreen('Day');
}
function predDayBack(){ renderPredWeek(startOfWeek(state.predict.currentDay)); }


