/* ===================== FARMER PUBLIC PROFILE ===================== */
function openFarmerProfile(farmerId){
  state.currentFarmerId = farmerId;
  const name = farmerName(farmerId);
  const f = farmerId===state.phone ? {location:state.location, bio:state.bio} : FARMERS.find(x=>x.id===farmerId);
  document.getElementById('fp-avatar').innerHTML = avatarInnerHTML(farmerAvatar(farmerId), name);
  document.getElementById('fp-name').textContent = name;
  document.getElementById('fp-loc').textContent = (f && f.location) ? '📍 '+f.location : 'Theraprice farmer';
  document.getElementById('fp-bio').textContent = (f && f.bio) ? f.bio : 'This farmer has not added a bio yet.';
  const vEl = document.getElementById('fp-vstatus');
  const verified = farmerVerified(farmerId);
  vEl.className = 'v-status '+(verified?'verified':'unverified');
  vEl.textContent = verified ? '✓ Verified Farmer' : '● Not Verified';

  const listings = PRODUCTS.filter(p=>p.farmerId===farmerId && p.status==='live');
  const grid = document.getElementById('fp-listings');
  grid.innerHTML = listings.length ? listings.map(p=>`
    <div class="product-card" onclick="openProduct(${p.id})">
      <div class="product-thumb thumb">${thumbHTML(p.image,p.color,false)}</div>
      <div class="product-body"><div class="p-name">${p.name}</div><div class="p-price">${p.price} <span class="p-unit">XAF/${unitLabel(p.unit)}</span></div></div>
    </div>`).join('') : `<div class="empty-state">No live listings from this farmer yet.</div>`;

  const fpMoments = document.getElementById('fp-moments');
  const theirMoments = MOMENTS.filter(m=>m.farmerId===farmerId);
  fpMoments.innerHTML = theirMoments.length ? theirMoments.map(m=>renderMomentCard(m)).join('') : `<div class="empty-state">No Moments posted yet.</div>`;
  renderReviews(farmerId);
  go('farmer');
}
function starsHTML(n, size){
  n = Math.round(n);
  let out = '';
  for(let i=1;i<=5;i++) out += i<=n ? '★' : '☆';
  return `<span class="star-display" ${size?`style="font-size:${size}px;"`:''}>${out}</span>`;
}
function renderReviews(farmerId){
  const list = REVIEWS.filter(r=>r.farmerId===farmerId);
  const summaryEl = document.getElementById('fp-review-summary');
  const listEl = document.getElementById('fp-reviews');
  const formEl = document.getElementById('fp-review-form');
  if(!list.length){
    summaryEl.innerHTML = `<span style="font-size:13px;color:var(--ink-soft);">No reviews yet — be the first to review ${farmerName(farmerId)}.</span>`;
  }else{
    const avg = list.reduce((a,r)=>a+r.stars,0)/list.length;
    summaryEl.innerHTML = `<div class="review-summary-row"><span class="avg">${avg.toFixed(1)}</span>${starsHTML(avg,20)}<span style="font-size:12.5px;color:var(--ink-soft);">based on ${list.length} review${list.length===1?'':'s'}</span></div>`;
  }
  listEl.innerHTML = list.length ? list.map(r=>`
    <div class="review-card"><div class="rev-head"><span class="rev-who">${r.author}</span><span class="rev-time">${r.time}</span></div>
      ${starsHTML(r.stars)}<p>${r.text}</p></div>`).join('') : '';
  if(!state.loggedIn){
    formEl.innerHTML = `<div class="comment-gate">Log in to leave a review.</div>`;
  }else if(farmerId===state.phone){
    formEl.innerHTML = '';
  }else{
    state.pendingReviewStars = 0;
    formEl.innerHTML = `<div class="field"><label>Your rating</label>
        <div class="star-input" id="reviewStarInput">${[1,2,3,4,5].map(n=>`<span data-n="${n}" onclick="setReviewStars(${n})">★</span>`).join('')}</div>
      </div>
      <div class="field"><label>Your review</label><textarea id="reviewText" rows="2" placeholder="How was this farmer's produce and delivery?"></textarea></div>
      <button class="btn btn-primary btn-sm" onclick="submitReview('${farmerId}')">Post review</button>`;
  }
}
function setReviewStars(n){
  state.pendingReviewStars = n;
  document.querySelectorAll('#reviewStarInput span').forEach(s=>s.classList.toggle('on', Number(s.dataset.n)<=n));
}
function submitReview(farmerId){
  if(!state.pendingReviewStars){ toast('Pick a star rating first.'); return; }
  const text = document.getElementById('reviewText').value.trim();
  if(!text){ toast('Add a few words about your experience.'); return; }
  REVIEWS.unshift({id:Date.now(), farmerId, authorId:state.phone, author:state.name, stars:state.pendingReviewStars, text, time:'just now'});
  toast('Review posted — thanks!');
  renderReviews(farmerId);
}

/* ===================== SOCIAL / MOMENTS ===================== */
function renderSocial(){
  const wrap = document.getElementById('composerWrap');
  if(state.loggedIn && state.role==='farmer'){
    wrap.innerHTML = `<div class="composer">
      <div class="composer-head"><span class="avatar">${avatarInnerHTML(state.avatar, state.name)}</span><div style="font-weight:700;font-size:13.5px;">${state.name}</div></div>
      <textarea id="momentText" placeholder="Share a harvest update, weather note, or what's coming to market…"></textarea>
      <div class="composer-thumb-row">
        <label class="thumb editable composer-thumb" id="momentThumbPicker"><input type="file" accept="image/*" class="vh" id="momentImageInput" onchange="handleMomentImageUpload(event)"></label>
        <span style="font-size:12px;color:var(--ink-soft);">Add a photo (optional)</span>
      </div>
      <div class="composer-actions"><span style="font-size:11.5px;color:var(--ink-soft);">Visible to every Theraprice buyer</span><button class="btn btn-primary btn-sm" onclick="postMoment()">Post Moment</button></div>
    </div>`;
    document.getElementById('momentThumbPicker').innerHTML += thumbHTML(state.momentDraftImage, '#F1F5EA', true, 'Add photo');
  }else if(state.loggedIn && state.role==='buyer'){
    wrap.innerHTML = `<div class="comment-gate">Only farmer accounts can post Moments. You can comment on any Moment below.</div>`;
  }else{
    wrap.innerHTML = `<div class="comment-gate">Log in as a buyer to comment, or as a farmer to post a Moment. <a href="#" onclick="go('login');return false;" style="color:var(--green-deep);font-weight:600;">Log in</a></div>`;
  }
  renderMomentsFeed();
}
function handleMomentImageUpload(e){
  const file = e.target.files[0]; if(!file) return;
  e.target.value='';
  openCropModal(file, url=>{ state.momentDraftImage=url; renderSocial(); const ta=document.getElementById('momentText'); if(ta) ta.focus(); }, 'square');
}
function postMoment(){
  const text = document.getElementById('momentText').value.trim();
  if(!text){ toast('Write something before posting.'); return; }
  ensureMyFarmerRecord();
  MOMENTS.unshift({id:Date.now(), farmerId:state.phone, text, image:state.momentDraftImage||null, time:'just now', comments:[], likes:0, likedByMe:false});
  state.momentDraftImage=null;
  toast('Moment posted.');
  renderSocial();
}
function renderMomentsFeed(){
  const feed = document.getElementById('momentsFeed');
  if(!MOMENTS.length){ feed.innerHTML = `<div class="social-empty">No Moments yet.</div>`; return; }
  feed.innerHTML = MOMENTS.map(m=>renderMomentCard(m)).join('');
}
function extractHashtags(text){ return (text.match(/#\w+/g) || []); }
function highlightHashtags(text){ return escapeHtml(text).replace(/#\w+/g, tag=>`<span class="hashtag">${tag}</span>`); }
function escapeHtml(s){ const d=document.createElement('div'); d.textContent=s; return d.innerHTML; }
function toggleMomentSave(id){
  if(!state.savedMoments) state.savedMoments = new Set();
  if(state.savedMoments.has(id)){ state.savedMoments.delete(id); toast('Removed from saved.'); }
  else { state.savedMoments.add(id); toast('Saved.'); }
  refreshMomentViews();
}
function toggleMomentMenu(id){
  document.querySelectorAll('.moment-menu.open').forEach(el=>{ if(el.id!=='momentMenu-'+id) el.classList.remove('open'); });
  const el = document.getElementById('momentMenu-'+id);
  if(el) el.classList.toggle('open');
}
function renderMomentCard(m){
  if(m.editing) return momentEditFormHTML(m, false);
  const name = farmerName(m.farmerId);
  const canComment = state.loggedIn;
  const canInteract = state.loggedIn;
  const isOwner = state.loggedIn && m.farmerId===state.phone;
  const saved = state.savedMoments && state.savedMoments.has(m.id);
  return `<div class="moment-card" id="moment-${m.id}">
      <div class="moment-head">
        <span class="avatar" onclick="openFarmerProfile('${m.farmerId}')" style="cursor:pointer;">${avatarInnerHTML(farmerAvatar(m.farmerId), name)}</span>
        <div style="flex:1;min-width:0;"><div class="who" onclick="openFarmerProfile('${m.farmerId}')">${name}</div><div class="meta">${m.time}</div></div>
        ${isOwner ? `<div class="moment-menu-wrap">
          <button class="moment-menu-btn" onclick="toggleMomentMenu(${m.id})">⋯</button>
          <div class="moment-menu" id="momentMenu-${m.id}">
            <button onclick="toggleMomentMenu(${m.id});startMomentEdit(${m.id})">✏️ Edit</button>
            <button onclick="toggleMomentMenu(${m.id});deleteMoment(${m.id})">🗑 Delete</button>
          </div></div>` : ''}
      </div>
      ${m.image ? `<div class="moment-photo-full thumb">${thumbHTML(m.image,'#F1F5EA',false)}</div>` : ''}
      <div class="moment-body"><p>${highlightHashtags(m.text)}</p></div>
      <div class="moment-foot">
        <button class="moment-like ${m.likedByMe?'liked':''}" onclick="${canInteract?`toggleMomentLike(${m.id})`:`toast('Log in to like Moments.')`}">${m.likedByMe?'❤️':'🤍'} ${m.likes||0}</button>
        <span class="moment-comment-count">💬 ${countAllComments(m)}</span>
        <button class="moment-save ${saved?'saved':''}" onclick="${canInteract?`toggleMomentSave(${m.id})`:`toast('Log in to save.')`}" title="Save">🔖</button>
      </div>
      <div class="comment-list">${m.comments.map(c=>renderCommentNode(m.id, c, 0)).join('')}</div>
      ${canComment ? `<div class="comment-form">
          <input type="text" placeholder="Write a comment…" id="cbox-${m.id}" onkeydown="if(event.key==='Enter'){submitComment(${m.id});}">
          <button class="btn btn-primary btn-sm" onclick="submitComment(${m.id})">Post</button>
        </div>` : (state.loggedIn ? '' : `<div class="comment-gate">Log in to comment.</div>`)}
    </div>`;
}
function countAllComments(m){
  function countList(list){ return list.reduce((n,c)=> n + 1 + (c.replies?countList(c.replies):0), 0); }
  return countList(m.comments);
}
function findCommentNode(m, nodeId){
  function search(list){
    for(const n of list){
      if(n.id===nodeId) return n;
      if(n.replies && n.replies.length){ const found = search(n.replies); if(found) return found; }
    }
    return null;
  }
  return search(m.comments);
}
function renderCommentNode(momentId, c, depth){
  const canInteract = state.loggedIn;
  const avatarSize = depth===0 ? 26 : 22;
  const fontSize = depth===0 ? 11 : 10;
  return `<div class="comment-row">
    <span class="avatar" style="width:${avatarSize}px;height:${avatarSize}px;font-size:${fontSize}px;">${c.author[0]}</span>
    <div style="flex:1;min-width:0;">
      <div class="comment-bubble"><div class="c-author">${c.author}</div><div class="c-text">${c.text}</div><div class="c-time">${c.time}</div></div>
      <div class="c-actions">
        <button class="c-action ${c.likedByMe?'liked':''}" onclick="${canInteract?`toggleCommentLike(${momentId},${c.id})`:`toast('Log in to like comments.')`}">${c.likedByMe?'❤️':'🤍'} ${c.likes>0?c.likes:'Like'}</button>
        <button class="c-action" onclick="${canInteract?`toggleReplyForm(${momentId},${c.id})`:`toast('Log in to reply.')`}">↩ Reply</button>
        ${c.authorId===state.phone ? `<button class="c-action" onclick="deleteCommentNode(${momentId},${c.id})">🗑 Delete</button>` : ''}
      </div>
      ${(c.replies&&c.replies.length) ? `<div class="reply-list">${c.replies.map(r=>renderCommentNode(momentId,r,depth+1)).join('')}</div>` : ''}
      <div class="reply-form vh" id="rform-${momentId}-${c.id}">
        <input type="text" placeholder="Reply to ${c.author}…" id="rbox-${momentId}-${c.id}" onkeydown="if(event.key==='Enter'){submitReply(${momentId},${c.id});}">
        <button class="btn btn-primary btn-sm" onclick="submitReply(${momentId},${c.id})">Reply</button>
      </div>
    </div>
  </div>`;
}
function toggleReplyForm(momentId, nodeId){
  const form = document.getElementById(`rform-${momentId}-${nodeId}`);
  if(!form) return;
  form.classList.toggle('vh');
  if(!form.classList.contains('vh')){ const inp = document.getElementById(`rbox-${momentId}-${nodeId}`); if(inp) inp.focus(); }
}
function toggleMomentLike(momentId){
  const m = MOMENTS.find(x=>x.id===momentId); if(!m) return;
  m.likedByMe = !m.likedByMe;
  m.likes = (m.likes||0) + (m.likedByMe ? 1 : -1);
  renderMomentsFeed();
}
function toggleCommentLike(momentId, nodeId){
  const m = MOMENTS.find(x=>x.id===momentId); if(!m) return;
  const c = findCommentNode(m, nodeId); if(!c) return;
  c.likedByMe = !c.likedByMe;
  c.likes = (c.likes||0) + (c.likedByMe ? 1 : -1);
  renderMomentsFeed();
}
/* ===================== NOTIFICATIONS ===================== */
let NOTIFICATIONS = [];
function pushNotification(userId, type, text, momentId){
  if(!userId) return;
  NOTIFICATIONS.unshift({id:Date.now()+Math.floor(Math.random()*1000), userId, type, text, momentId, time:'just now', read:false});
  if(userId===state.phone) renderNotifBell();
}
function unreadNotifCount(){ return NOTIFICATIONS.filter(n=>n.userId===state.phone && !n.read).length; }
function renderNotifBell(){
  const badge = document.getElementById('notifBadge');
  if(!badge) return;
  const count = unreadNotifCount();
  badge.textContent = count>9 ? '9+' : count;
  badge.style.display = count>0 ? 'flex' : 'none';
}
function toggleNotifPanel(){
  const panel = document.getElementById('notifPanel');
  if(!panel) return;
  panel.classList.toggle('open');
  if(panel.classList.contains('open')) renderNotifList();
}
function notifIcon(type){ return type==='comment' ? '💬' : type==='reply' ? '↩️' : type==='verification' ? '🛡️' : type==='delivery' ? '📦' : type==='report' ? '🚩' : '🔔'; }
function renderNotifList(){
  const el = document.getElementById('notifList');
  if(!el) return;
  const mine = NOTIFICATIONS.filter(n=>n.userId===state.phone);
  if(!mine.length){ el.innerHTML = `<div class="gen-empty" style="padding:24px 16px;"><div class="ic">🔔</div>No notifications yet.</div>`; return; }
  el.innerHTML = mine.map(n=>`<div class="notif-row ${n.read?'':'unread'}" onclick="openNotification(${n.id})">
    <span class="notif-ic">${notifIcon(n.type)}</span>
    <div><div class="notif-text">${n.text}</div><div class="notif-time">${n.time}</div></div>
  </div>`).join('');
}
function openNotification(id){
  const n = NOTIFICATIONS.find(x=>x.id===id); if(!n) return;
  n.read = true;
  renderNotifBell(); renderNotifList();
  toggleNotifPanel();
  if(n.momentId!=null) go('social');
}

/* ===================== COMMENTS / REPLIES ===================== */
function submitComment(momentId){
  const input = document.getElementById('cbox-'+momentId);
  const text = input.value.trim();
  if(!text) return;
  const m = MOMENTS.find(x=>x.id===momentId);
  m.comments.push({id:Date.now()+Math.floor(Math.random()*1000), author:state.name, text, time:'just now', authorId:state.phone, likes:0, likedByMe:false, replies:[]});
  input.value='';
  renderMomentsFeed();
  if(m.farmerId!==state.phone){
    pushNotification(m.farmerId, 'comment', `${state.name} commented on your Moment: "${text.slice(0,60)}${text.length>60?'…':''}"`, momentId);
  }
}
function submitReply(momentId, nodeId){
  const input = document.getElementById(`rbox-${momentId}-${nodeId}`);
  const text = input.value.trim();
  if(!text) return;
  const m = MOMENTS.find(x=>x.id===momentId); if(!m) return;
  const parent = findCommentNode(m, nodeId); if(!parent) return;
  if(!parent.replies) parent.replies = [];
  parent.replies.push({id:Date.now()+Math.floor(Math.random()*1000), author:state.name, text, time:'just now', authorId:state.phone, likes:0, likedByMe:false, replies:[]});
  input.value='';
  renderMomentsFeed();
  if(parent.authorId && parent.authorId!==state.phone){
    pushNotification(parent.authorId, 'reply', `${state.name} replied to your comment: "${text.slice(0,60)}${text.length>60?'…':''}"`, momentId);
  }
}
function deleteCommentNode(momentId, nodeId){
  const m = MOMENTS.find(x=>x.id===momentId); if(!m) return;
  function removeFrom(list){
    const idx = list.findIndex(c=>c.id===nodeId);
    if(idx!==-1){ list.splice(idx,1); return true; }
    for(const c of list){ if(c.replies && removeFrom(c.replies)) return true; }
    return false;
  }
  removeFrom(m.comments);
  renderMomentsFeed();
  toast('Comment deleted.');
}

/* ===================== PROFILE ===================== */
const TABS_BASE = [
  {id:'info', label:'My Profile', icon:'👤'},
  {id:'favorites', label:'Favorites', icon:'♡'},
  {id:'listings', label:'', icon:'📋'},
  {id:'orders', label:'My Orders', icon:'🧾', farmerOnly:true},
  {id:'moments', label:'My Moments', icon:'📣', farmerOnly:true},
  {id:'payouts', label:'Payouts', icon:'💰', farmerOnly:true},
  {id:'comments', label:'My Comments', icon:'💬'},
  {id:'verification', label:'Verification', icon:'🛡️', farmerOnly:true}
];
function renderProfile(){
  document.getElementById('profileAvatar').innerHTML = avatarInnerHTML(state.avatar, state.name);
  document.getElementById('profileName').textContent = state.name;
  document.getElementById('profileRoleLine').textContent = (state.role==='farmer' ? '🌾 Farmer / Seller' : '🛒 Buyer') + (state.email ? ' · '+state.email : '');
  const vEl = document.getElementById('profileVStatus');
  if(state.role==='farmer'){ vEl.style.display='inline-flex'; setStatusPill(vEl, state.verification.status); } else { vEl.style.display='none'; }

  document.getElementById('listingsTitle').textContent = state.role==='farmer' ? 'My Listings' : 'My Orders';
  document.getElementById('listingsDesc').textContent = state.role==='farmer'
    ? 'Active, pending, and rejected listings, with the reason shown.'
    : 'Your active and past orders. This is private and only visible to you.';
  document.getElementById('addListingBtn').style.display = state.role==='farmer' ? 'inline-flex' : 'none';

  const tabs = TABS_BASE.filter(t=> !t.farmerOnly || state.role==='farmer').map(t=>{
    if(t.id==='listings') t.label = state.role==='farmer' ? 'My Listings' : 'My Orders';
    return t;
  });
  document.getElementById('profileTabs').innerHTML = tabs.map((t,i)=>{
    let badge='';
    if(t.id==='verification' && state.verification.status==='pending') badge='<span class="tab-badge">pending</span>';
    return `<button class="profile-tab ${i===0?'active':''}" data-tab="${t.id}" onclick="switchProfileTab('${t.id}')">${t.icon} ${t.label}${badge}</button>`;
  }).join('');

  fillInfoFields();
  document.getElementById('avatarThumb').innerHTML = `<input type="file" accept="image/*" class="vh" id="avatarInput" onchange="handleAvatarUpload(event)">` + thumbHTML(state.avatar, '#F1F5EA', true, 'Add photo');
  setEditMode(state.editingInfo);

  renderFavorites();
  renderListings();
  renderFarmerOrders();
  renderMomentsTab();
  renderPayouts();
  renderMyComments();
  renderVerification();
  switchProfileTab('info');
}
function fillInfoFields(){
  document.getElementById('info-name').value = state.name;
  document.getElementById('info-phone').value = state.phone;
  document.getElementById('info-email').value = state.email || '—';
  document.getElementById('info-role').value = state.role==='farmer' ? 'Farmer / Seller' : 'Buyer';
  document.getElementById('info-location-label').textContent = state.role==='farmer' ? 'Farm location' : 'Location';
  document.getElementById('info-bio-wrap').style.display = state.role==='farmer' ? 'block' : 'none';
  document.getElementById('info-location').value = state.location || '';
  document.getElementById('info-bio').value = state.bio;
}
function toggleEditInfo(){ setEditMode(!state.editingInfo); }
function setEditMode(on){
  state.editingInfo = on;
  ['info-name','info-phone','info-bio'].forEach(id=>{
    const el = document.getElementById(id); if(el) el.readOnly = !on;
  });
  document.getElementById('saveInfoBtn').style.display = on ? 'inline-flex' : 'none';
  document.getElementById('editToggleBtn').textContent = on ? 'Cancel' : 'Edit profile';
  document.getElementById('editToggleBtn').onclick = on ? ()=>{ setEditMode(false); fillInfoFields(); } : toggleEditInfo;
}
function handleAvatarUpload(e){
  const file = e.target.files[0]; if(!file) return;
  e.target.value='';
  openCropModal(file, url=>{
    state.avatar = url;
    if(state.role==='farmer'){ ensureMyFarmerRecord(); }
    document.getElementById('avatarThumb').innerHTML = `<input type="file" accept="image/*" class="vh" id="avatarInput" onchange="handleAvatarUpload(event)">` + thumbHTML(state.avatar, '#F1F5EA', true, 'Add photo');
    document.getElementById('profileAvatar').innerHTML = avatarInnerHTML(state.avatar, state.name);
    renderAuthArea();
    toast('Profile photo updated.');
  }, 'circle');
}
function saveProfileInfo(){
  state.name = document.getElementById('info-name').value.trim() || state.name;
  state.phone = document.getElementById('info-phone').value.trim() || state.phone;
  state.bio = document.getElementById('info-bio').value.trim();
  if(state.role==='farmer') ensureMyFarmerRecord();
  setEditMode(false);
  document.getElementById('profileName').textContent = state.name;
  renderAuthArea();
  toast('Profile updated.');
}
function setStatusPill(el, status){
  el.className='v-status '+status;
  el.textContent = status==='verified' ? '✓ Verified Farmer' : status==='pending' ? '⏳ Verification Pending' : '● Not Verified';
}
function switchProfileTab(id){
  document.querySelectorAll('.profile-tab').forEach(b=>b.classList.toggle('active', b.dataset.tab===id));
  document.querySelectorAll('.profile-panel').forEach(p=>p.classList.remove('active'));
  document.getElementById('panel-'+id).classList.add('active');
}
function renderFavorites(){
  const el = document.getElementById('favList');
  if(!state.favorites.size){ el.innerHTML = `<div class="fav-empty"><div class="ic">♡</div>Nothing saved yet — tap Save on any product to add it here.</div>`; return; }
  el.innerHTML = [...state.favorites].map(id=>{
    const p = PRODUCTS.find(x=>x.id===id);
    if(!p) return '';
    return `<div class="mylist-row"><div class="mylist-left"><div class="mylist-thumb thumb">${thumbHTML(p.image,p.color,false)}</div>
      <div><div class="mylist-name">${p.name}</div><div class="mylist-sub">${farmerName(p.farmerId)} · ${p.price.toLocaleString()} XAF/${unitLabel(p.unit)}</div></div></div>
      <button class="btn btn-sm btn-outline" onclick="openProduct(${p.id})">View</button></div>`;
  }).join('');
}
function renderListings(){
  const el = document.getElementById('listingsList');
  if(state.role==='farmer'){
    const mine = PRODUCTS.filter(p=>isCurrentFarmer(p.farmerId));
    if(!mine.length){ el.innerHTML = `<div class="gen-empty"><div class="ic">📋</div>You haven't listed any products yet.</div>`; return; }
    el.innerHTML = mine.map(p=>{
      const statusLabel = p.status==='live' ? 'Live' : p.status==='pending' ? 'Pending admin review' : 'Rejected';
      const cls = p.status==='live' ? 'live' : p.status==='pending' ? 'review' : 'rejected';
      return `<div class="mylist-row"><div class="mylist-left"><div class="mylist-thumb thumb">${thumbHTML(p.image,p.color,false)}</div>
        <div><div class="mylist-name">${p.name}</div><div class="mylist-sub">${p.price.toLocaleString()} XAF/${unitLabel(p.unit)}${p.status==='rejected' && p.rejectionReason ? ` · <span style="color:var(--rust);">Reason: ${p.rejectionReason}</span>` : ''}</div></div></div>
        <div class="mylist-right"><span class="status-tag ${cls}">${statusLabel}</span><button class="btn btn-sm btn-danger" onclick="removeListing(${p.id})">Remove</button></div></div>`;
    }).join('');
  }else{
    if(!state.orders.length){ el.innerHTML = `<div class="gen-empty"><div class="ic">📋</div>No orders yet — visit the marketplace to place one.</div>`; return; }
    el.innerHTML = state.orders.map(d=>{
      const statusLabel = d.status==='delivered' ? 'Delivered ✓' : d.status==='out_for_delivery' ? 'Out for delivery' : d.status==='review' ? 'Under review' : 'Rejected';
      const cls = d.status==='delivered' ? 'live' : d.status==='out_for_delivery' ? 'review' : d.status==='review' ? 'review' : 'rejected';
      const notDelivered = d.status!=='delivered';
      return `<div class="mylist-row"><div class="mylist-left"><div class="mylist-thumb thumb">${thumbHTML(null,'#F3E9D6',false)}</div>
        <div><div class="mylist-name">${d.name}${d.reported ? ' <span style="color:var(--rust);font-size:11px;">🚩 Reported</span>' : ''}</div><div class="mylist-sub">${d.unit?'Sold by the '+d.unit:''}${d.note?' · '+d.note:''}</div></div></div>
        <div class="mylist-right">
          <span class="status-tag ${cls}">${statusLabel}</span>
          ${d.status==='out_for_delivery' ? `<button class="btn btn-primary btn-sm" onclick="confirmDelivery(${d.id})">Confirm delivery received</button>` : ''}
          ${notDelivered && !d.reported ? `<button class="btn btn-outline btn-sm" style="color:var(--rust);border-color:var(--rust);" onclick="openReportModal(${d.id})">🚩 Report</button>` : ''}
          ${d.reported ? `<span style="font-size:11px;color:var(--ink-soft);">Reported — admin notified</span>` : ''}
        </div></div>`;
    }).join('');
  }
}
function removeListing(id){
  PRODUCTS = PRODUCTS.filter(p=>p.id!==id);
  renderListings(); renderMarketplace(); renderHomePanel(); renderTicker();
  toast('Listing removed.');
}
function renderFarmerOrders(){
  const el = document.getElementById('farmerOrdersList');
  if(!el || state.role!=='farmer') return;
  const mine = SALES.filter(s=>s.farmerId===state.phone);
  if(!mine.length){ el.innerHTML = `<div class="gen-empty"><div class="ic">🧾</div>No orders yet. Orders will appear here as soon as a buyer purchases one of your listings.</div>`; return; }
  el.innerHTML = mine.map(s=>{
    const delivered = s.status==='delivered';
    const statusLabel = delivered ? 'Delivered ✓' : 'Out for delivery';
    const cls = delivered ? 'live' : 'review';
    return `<div class="mylist-row"><div class="mylist-left"><div class="mylist-thumb thumb">${thumbHTML(null,'#F1F5EA',false)}</div>
      <div><div class="mylist-name">${s.productName} <span style="font-weight:400;color:var(--ink-soft);">× ${s.qty}</span>${s.reported ? ' <span style="color:var(--rust);font-size:11px;">🚩 Reported</span>' : ''}</div>
      <div class="mylist-sub">Order ${s.orderRef} · Buyer: ${s.buyerName}</div></div></div>
      <div class="mylist-right"><span class="status-tag ${cls}">${statusLabel}</span>${!delivered ? `<button class="btn btn-primary btn-sm" onclick="farmerConfirmDelivery(${s.id})">Confirm delivery</button>` : ''}</div></div>`;
  }).join('');
}
function renderPayouts(){
  const summaryEl = document.getElementById('payoutsSummary');
  const listEl = document.getElementById('payoutsList');
  if(!summaryEl || !listEl) return;
  if(state.role!=='farmer'){ return; }
  const mine = SALES.filter(s=>s.farmerId===state.phone);
  if(!mine.length){
    summaryEl.innerHTML='';
    listEl.innerHTML = `<div class="gen-empty"><div class="ic">💰</div>No sales yet. Payouts appear here once a buyer orders one of your listings.</div>`;
    return;
  }
  const totalGross = mine.reduce((a,s)=>a+s.gross,0);
  const totalCommission = mine.reduce((a,s)=>a+s.commission,0);
  const paidSoFar = mine.reduce((a,s)=>a + s.immediatePay + (s.status==='delivered' ? s.heldAmount : 0), 0);
  const heldPending = mine.reduce((a,s)=>a + (s.status==='delivered' ? 0 : s.heldAmount), 0);
  const pendingCount = mine.filter(s=>s.status!=='delivered').length;
  summaryEl.innerHTML = `
    <div class="signal-card"><div style="font-size:11px;color:var(--ink-soft);">Total sales</div><div style="font-size:19px;font-weight:800;">${totalGross.toLocaleString()} XAF</div></div>
    <div class="signal-card"><div style="font-size:11px;color:var(--ink-soft);">Platform fee (3%)</div><div style="font-size:19px;font-weight:800;color:var(--down);">-${totalCommission.toLocaleString()} XAF</div></div>
    <div class="signal-card" style="border-color:var(--up);"><div style="font-size:11px;color:var(--ink-soft);">Paid to you</div><div style="font-size:19px;font-weight:800;color:var(--up);">${paidSoFar.toLocaleString()} XAF</div></div>
    <div class="signal-card" style="border-color:var(--stable);"><div style="font-size:11px;color:var(--ink-soft);">Held until delivery</div><div style="font-size:19px;font-weight:800;color:var(--stable);">${heldPending.toLocaleString()} XAF</div></div>`;
  listEl.innerHTML = `<div style="font-size:11.5px;color:var(--ink-soft);margin-bottom:8px;">40% is released the moment an order is paid for; the remaining 60% releases once delivery is confirmed. ${pendingCount} sale${pendingCount===1?'':'s'} still awaiting that release.</div>` +
    mine.map(s=>{
      const delivered = s.status==='delivered';
      return `<div class="mylist-row"><div class="mylist-left"><div class="mylist-thumb thumb">${thumbHTML(null,'#F1F5EA',false)}</div>
        <div><div class="mylist-name">${s.productName} <span style="font-weight:400;color:var(--ink-soft);">× ${s.qty}</span>${s.reported ? ' <span style="color:var(--rust);font-size:11px;">🚩 Reported</span>' : ''}</div>
        <div class="mylist-sub">Sold to ${s.buyerName} · Gross ${s.gross.toLocaleString()} XAF − 3% fee ${s.commission.toLocaleString()} = <b style="color:var(--ink);">${s.net.toLocaleString()} XAF net</b><br>
        Paid at order (40%): ${s.immediatePay.toLocaleString()} XAF · ${delivered ? `Released on delivery (60%): ${s.heldAmount.toLocaleString()} XAF` : `Held until delivery (60%): ${s.heldAmount.toLocaleString()} XAF`}</div></div></div>
        <span class="status-tag ${delivered?'live':'review'}">${delivered?'Fully paid':'Partially paid'}</span></div>`;
    }).join('');
}
function momentEditFormHTML(m, mini){
  const img = m.editImage!==undefined ? m.editImage : m.image;
  return `<div class="moment-card${mini?' mini':''}">
      <textarea id="edit-moment-${m.id}" style="width:100%;min-height:70px;font-family:inherit;font-size:13px;border:1px solid var(--line);border-radius:10px;padding:8px 10px;">${m.text}</textarea>
      <div class="edit-moment-photo-row" style="margin-top:10px;display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
        <div class="thumb" style="width:56px;height:56px;border-radius:10px;">${thumbHTML(img, '#F1F5EA', false)}</div>
        <label class="btn btn-outline btn-sm" style="cursor:pointer;">Change photo<input type="file" accept="image/*" class="vh" onchange="handleMomentEditImageUpload(event,${m.id})"></label>
        ${img ? `<button class="btn btn-outline btn-sm" onclick="removeMomentEditImage(${m.id})">Remove photo</button>` : ''}
      </div>
      <div style="margin-top:10px;display:flex;gap:8px;">
        <button class="btn btn-primary btn-sm" onclick="saveMomentEdit(${m.id})">Save</button>
        <button class="btn btn-secondary btn-sm" onclick="cancelMomentEdit(${m.id})">Cancel</button>
      </div>
    </div>`;
}
function renderMomentsTab(){
  const el = document.getElementById('momentsList');
  if(state.role!=='farmer'){ el.innerHTML = `<div class="gen-empty"><div class="ic">📣</div>Moments are a farmer feature.</div>`; return; }
  const mine = MOMENTS.filter(m=>m.farmerId===state.phone);
  if(!mine.length){ el.innerHTML = `<div class="gen-empty"><div class="ic">📣</div>You haven't posted a Moment yet. Try the Social tab.</div>`; return; }
  el.innerHTML = mine.map(m=> m.editing ? momentEditFormHTML(m, true) : `<div class="moment-card mini">${m.image ? `<div class="moment-photo thumb" style="margin-bottom:8px;">${thumbHTML(m.image,'#F1F5EA',false)}</div>` : ''}<p>${m.text}</p><div class="moment-meta" style="font-size:11.5px;color:var(--ink-soft);">${m.time} · ${countAllComments(m)} comment${countAllComments(m)===1?'':'s'} · ❤️ ${m.likes||0}
    <button class="cart-remove" style="margin-left:10px;" onclick="startMomentEdit(${m.id})">Edit</button>
    <button class="cart-remove" style="margin-left:10px;" onclick="deleteMoment(${m.id})">Delete</button></div></div>`).join('');
}
function startMomentEdit(id){ const m=MOMENTS.find(x=>x.id===id); if(m){ m.editing=true; m.editImage=m.image; refreshMomentViews(); } }
function cancelMomentEdit(id){ const m=MOMENTS.find(x=>x.id===id); if(m){ m.editing=false; delete m.editImage; refreshMomentViews(); } }
function handleMomentEditImageUpload(e, id){
  const file = e.target.files[0]; if(!file) return;
  e.target.value='';
  openCropModal(file, url=>{ const m=MOMENTS.find(x=>x.id===id); if(!m) return; m.editImage=url; refreshMomentViews(); }, 'square');
}
function removeMomentEditImage(id){ const m=MOMENTS.find(x=>x.id===id); if(m){ m.editImage=null; refreshMomentViews(); } }
function saveMomentEdit(id){
  const m = MOMENTS.find(x=>x.id===id); if(!m) return;
  const val = document.getElementById('edit-moment-'+id).value.trim();
  if(!val){ toast('Moment text cannot be empty.'); return; }
  m.text = val;
  m.image = m.editImage!==undefined ? m.editImage : m.image;
  delete m.editImage;
  m.editing = false;
  refreshMomentViews();
  toast('Moment updated.');
}
function deleteMoment(id){ MOMENTS = MOMENTS.filter(m=>m.id!==id); refreshMomentViews(); toast('Moment deleted.'); }
function refreshMomentViews(){
  if(document.getElementById('momentsList')) renderMomentsTab();
  if(document.getElementById('momentsFeed')) renderMomentsFeed();
}
function renderMyComments(){
  const el = document.getElementById('myCommentsList');
  const mine = [];
  MOMENTS.forEach(m=>{ m.comments.forEach(c=>{ if(c.authorId===state.phone) mine.push({moment:m, comment:c}); }); });
  if(!mine.length){ el.innerHTML = `<div class="gen-empty"><div class="ic">💬</div>No comments yet — visit the Social tab to leave one.</div>`; return; }
  el.innerHTML = mine.map(({moment,comment})=>`<div class="mylist-row"><div><div class="mylist-name">"${comment.text}"</div><div class="mylist-sub">On ${farmerName(moment.farmerId)}'s Moment · ${comment.time}</div></div>
    <button class="btn btn-sm btn-outline" onclick="go('social')">View</button></div>`).join('');
}

/* ===================== VERIFICATION (farmer only) ===================== */
function renderVerification(){
  const el = document.getElementById('verificationBody');
  const v = state.verification;
  if(state.role!=='farmer'){ el.innerHTML = `<div class="gate-card">🛡️ Identity verification is only required for farmer accounts.<br>Buyer accounts don't need to verify.</div>`; return; }
  if(v.status==='verified'){
    el.innerHTML = `<div class="status-panel verified"><h3>✓ You're a Verified Farmer</h3>
      <p>Your ID, live selfie match, and farming documents have all been confirmed. Your listings now carry the Verified badge, and buyers can see your trust status on your public profile.</p></div>`;
    return;
  }
  if(v.status==='pending'){
    el.innerHTML = `<div class="status-panel pending"><h3>⏳ Verification pending review</h3>
      <p>Your documents were submitted and are being reviewed. This typically takes 24–48 hours, and we'll notify you by SMS once it's done.</p>
      <ul class="checklist" style="margin-top:16px;">
        <li>✅ ID card — front uploaded</li><li>✅ ID card — back uploaded</li><li>✅ Selfie captured in-app</li>
        <li>✅ Farming documents uploaded</li><li>✅ Digital contract accepted</li>
      </ul></div>`;
    return;
  }
  const step = v.step;
  const stepLabels = ['ID front','ID back','Selfie','Documents','Review & submit'];
  let stepsHtml = stepLabels.map((lbl,i)=>{
    const n=i+1; const cls = n<step ? 'done' : n===step ? 'current' : '';
    return `<div class="v-step ${cls}"><div class="dot">${n<step?'✓':n}</div><span>${lbl}</span></div>` + (i<stepLabels.length-1 ? `<div class="v-step-sep ${n<step?'done':''}"></div>` : '');
  }).join('');
  const introBanner = `<div class="verify-intro"><span class="ic">🛡️</span><p><b>Why we verify farmers.</b> A quick ${stepLabels.length}-step check confirms you're a real person with real produce to sell, so buyers can trust every listing on Theraprice. Takes about 5 minutes.</p></div>`;
  let content='';
  if(step===1){
    content = `<h3>Step 1 — ID card: front</h3><p class="desc">Prepare a Passport, National ID, or Resident Card. Upload a clear photo of the front side.</p>
      <label class="upload-box ${v.files.idFront?'attached':''}" for="file-idFront"><div class="ic">🪪</div><div><b>${v.files.idFront?'ID front uploaded':'Tap to upload ID card — front'}</b></div><div style="font-size:11.5px;margin-top:4px;">JPG or PNG, front side visible</div>
      <div class="fname" id="fname-idFront">${v.files.idFront ? '✓ ID front attached' : ''}</div></label>
      <input type="file" id="file-idFront" accept="image/*" class="vh" onchange="markFile(event,'idFront')">
      <div class="step-actions"><span></span><button class="btn btn-primary" onclick="verStepNext(1)" ${v.files.idFront?'':'disabled'}>Continue</button></div>`;
  }else if(step===2){
    content = `<h3>Step 2 — ID card: back</h3><p class="desc">The card you uploaded has basic, essential information on its back side. Flip the card and take a photo.</p>
      <label class="upload-box ${v.files.idBack?'attached':''}" for="file-idBack"><div class="ic">🪪</div><div><b>${v.files.idBack?'ID back uploaded':'Tap to upload ID card — back'}</b></div><div style="font-size:11.5px;margin-top:4px;">JPG or PNG, back side visible</div>
      <div class="fname" id="fname-idBack">${v.files.idBack ? '✓ ID back attached' : ''}</div></label>
      <input type="file" id="file-idBack" accept="image/*" class="vh" onchange="markFile(event,'idBack')">
      <div class="step-actions"><button class="btn btn-outline" onclick="verStepBack()">Back</button><button class="btn btn-primary" onclick="verStepNext(2)" ${v.files.idBack?'':'disabled'}>Continue</button></div>`;
  }else if(step===3){
    content = `<h3>Step 3 — Take a selfie</h3><p class="desc">Take a live photo in the app so we can confirm the person holding the phone matches the ID card photo.</p>
      <label class="upload-box selfie-box ${v.files.selfie?'attached':''}" for="file-selfie"><div class="ic">🤳</div><div><b>${v.files.selfie?'Selfie captured':'Tap to take a selfie'}</b></div><div style="font-size:11.5px;margin-top:4px;">Keep your face centered, good lighting, fully inside the frame</div>
      <div class="fname" id="fname-selfie">${v.files.selfie ? '✓ Identity verified' : ''}</div></label>
      <input type="file" id="file-selfie" accept="image/*" capture="user" class="vh" onchange="markFile(event,'selfie')">
      <div class="step-actions"><button class="btn btn-outline" onclick="verStepBack()">Back</button><button class="btn btn-primary" onclick="verStepNext(3)" ${v.files.selfie?'':'disabled'}>Continue</button></div>`;
  }else if(step===4){
    content = `<h3>Step 4 — Upload documents</h3><p class="desc">Upload documents showing you genuinely have produce or farmland to sell — a land title, cooperative letter, or farm photo. You can attach more than one.</p>
      <label class="upload-box ${v.files.documents?'attached':''}" for="file-documents"><div class="ic">🌾</div><div><b>${v.files.documents?'Documents uploaded':'Tap to upload farming documents'}</b></div><div style="font-size:11.5px;margin-top:4px;">Images or PDF, multiple files allowed</div>
      <div class="fname" id="fname-documents">${v.files.documents ? '✓ Documents attached' : ''}</div></label>
      <input type="file" id="file-documents" accept="image/*,.pdf" multiple class="vh" onchange="markFile(event,'documents')">
      <div class="step-actions"><button class="btn btn-outline" onclick="verStepBack()">Back</button><button class="btn btn-primary" onclick="verStepNext(4)" ${v.files.documents?'':'disabled'}>Continue</button></div>`;
  }else if(step===5){
    content = `<h3>Step 5 — Review &amp; submit</h3><p class="desc">The last step before your application goes to review.</p>
      <ul class="checklist" style="margin-bottom:16px;">
        <li>✅ ID card — front</li><li>✅ ID card — back</li><li>✅ Selfie captured</li><li>✅ Farming documents</li>
      </ul>
      <div class="check-row"><input type="checkbox" id="chk-contract" onchange="toggleConsent('contract')" ${v.contract?'checked':''}>
        <label for="chk-contract">I accept the Theraprice farmer digital contract. I understand fraudulent listings or scam behavior can result in account suspension.</label></div>
      <div class="check-row"><input type="checkbox" id="chk-locator" onchange="toggleConsent('locator')" ${v.locator?'checked':''}>
        <label for="chk-locator">(Optional) Enable consent-based device location, so Theraprice can help trace stolen goods or resolve confirmed fraud cases. I can review this anytime.</label></div>
      <div class="step-actions"><button class="btn btn-outline" onclick="verStepBack()">Back</button><button class="btn btn-primary" onclick="submitVerification()" ${v.contract?'':'disabled'}>Submit for review</button></div>`;
  }
  el.innerHTML = `<h3 style="margin-bottom:2px;">Farmer Verification</h3><p class="desc">Every farmer account is verified before its listings go live, so buyers can trust every listing on Theraprice.</p>
    ${introBanner}<div class="v-steps">${stepsHtml}</div>${content}`;
}
function markFile(e, kind){
  const files = e.target.files;
  if(!files || !files.length) return;
  if(kind==='documents'){
    const readers = Array.from(files).map(f=>new Promise(res=>readFileAsDataURL(f, res)));
    Promise.all(readers).then(urls=>{
      state.verification.files.documents = urls;
      renderVerification();
      toast('Documents attached.');
    });
  }else{
    readFileAsDataURL(files[0], url=>{
      state.verification.files[kind] = url;
      renderVerification();
      toast('File attached.');
    });
  }
}
function toggleConsent(kind){ state.verification[kind] = !state.verification[kind]; }
function verStepNext(current){ state.verification.step = current+1; renderVerification(); }
function verStepBack(){ state.verification.step = Math.max(1, state.verification.step-1); renderVerification(); }
function submitVerification(){
  state.verification.status='pending';
  saveAccount();
  renderVerification(); renderProfile();
  toast('Verification submitted — an admin will review it shortly.');
}

/* ===================== ADMIN DASHBOARD (hidden link, no login) =====================
   Real human-review queues, per the workflow spec: identity verification and product
   verification are reviewed separately — being an ID-verified farmer does not
   auto-approve a listing, and vice versa. */
function renderAdminDashboard(){
  if(state.phone) saveAccount(); // make sure the active session's own submissions are reflected in ACCOUNTS
  const pendingFarmers = Object.values(ACCOUNTS).filter(a=>a.role==='farmer' && a.verification && a.verification.status==='pending');
  const idQueueEl = document.getElementById('adminIdentityQueue');
  idQueueEl.innerHTML = pendingFarmers.length ? pendingFarmers.map(a=>{
    const v = a.verification;
    const idThumbs = ['idFront','idBack','selfie'].map(k=> v.files[k]
      ? `<img src="${v.files[k]}" class="admin-doc-thumb" alt="${k}">`
      : `<div class="admin-doc-thumb empty">No ${k}</div>`).join('');
    const docs = (Array.isArray(v.files.documents) ? v.files.documents : []);
    const docThumbs = docs.length ? docs.map(u=>`<img src="${u}" class="admin-doc-thumb" alt="document">`).join('') : `<div class="admin-doc-thumb empty">No documents</div>`;
    return `<div class="admin-card">
      <div class="admin-card-head"><b>${a.name}</b><span>${a.phone} · ${a.location||'No location set'}</span></div>
      <div class="admin-doc-row">${idThumbs}${docThumbs}</div>
      <div class="admin-card-actions">
        <button class="btn btn-primary btn-sm" onclick="adminApproveIdentity('${a.phone}')">✓ Approve</button>
        <button class="btn btn-danger btn-sm" onclick="openAdminRejectModal('identity','${a.phone}')">✕ Reject</button>
      </div>
    </div>`;
  }).join('') : `<div class="gen-empty"><div class="ic">🛡️</div>No pending identity verifications.</div>`;

  const pendingProducts = PRODUCTS.filter(p=>p.status==='pending');
  const prodQueueEl = document.getElementById('adminProductQueue');
  prodQueueEl.innerHTML = pendingProducts.length ? pendingProducts.map(p=>`
    <div class="admin-card">
      <div class="admin-card-head"><b>${p.name}</b><span>${farmerName(p.farmerId)} · ${p.price.toLocaleString()} XAF/${unitLabel(p.unit)} · ${p.category}</span></div>
      <div class="admin-doc-row"><div class="thumb admin-prod-thumb">${thumbHTML(p.image, p.color, false)}</div></div>
      <div class="admin-card-actions">
        <button class="btn btn-primary btn-sm" onclick="adminApproveProduct(${p.id})">✓ Approve</button>
        <button class="btn btn-danger btn-sm" onclick="openAdminRejectModal('product',${p.id})">✕ Reject</button>
      </div>
    </div>`).join('') : `<div class="gen-empty"><div class="ic">🧺</div>No pending product listings.</div>`;

  const reported = SALES.filter(s=>s.reported);
  const reportsEl = document.getElementById('adminReportsQueue');
  reportsEl.innerHTML = reported.length ? reported.map(s=>`
    <div class="admin-card">
      <div class="admin-card-head"><b>${s.productName} — Order ${s.orderRef}</b><span>Buyer: ${s.buyerName} · Farmer: ${farmerName(s.farmerId)}</span></div>
      <p style="font-size:13px;margin-bottom:14px;color:var(--ink);">"${s.reportReason}"</p>
      <div class="admin-card-actions">
        <button class="btn btn-primary btn-sm" onclick="adminResolveReport(${s.id})">✓ Mark Resolved</button>
      </div>
    </div>`).join('') : `<div class="gen-empty"><div class="ic">🚩</div>No delivery reports right now.</div>`;
}
function adminResolveReport(id){
  const sale = SALES.find(s=>s.id===id);
  if(sale){
    sale.reported = false;
    pushNotification(sale.farmerId, 'report', `The delivery report for order ${sale.orderRef} (${sale.productName}) was marked resolved.`, null);
    if(sale.buyerId) pushNotification(sale.buyerId, 'report', `An admin followed up on your report for order ${sale.orderRef} (${sale.productName}) — it's now marked resolved.`, null);
  }
  const order = state.orders.find(o=>o.id===id);
  if(order) order.reported = false;
  renderListings(); renderFarmerOrders();
  renderAdminDashboard();
  toast('Report marked resolved.');
}
function adminApproveIdentity(phone){
  const acc = ACCOUNTS[phone];
  if(!acc) return;
  acc.verification.status='verified'; acc.verification.rejectionReason=null;
  if(state.phone===phone){ renderVerification(); renderProfile(); }
  pushNotification(phone, 'verification', "You're now a Verified Farmer — you can list products for admin review.", null);
  renderAdminDashboard();
  toast('Farmer approved.');
}
function adminApproveProduct(id){
  const p = PRODUCTS.find(x=>x.id===id);
  if(!p) return;
  p.status='live'; p.rejectionReason=null;
  pushNotification(p.farmerId, 'verification', `Your listing "${p.name}" was approved and is now live.`, null);
  renderListings(); renderMarketplace(); renderHomePanel(); renderTicker();
  renderAdminDashboard();
  toast('Product approved and live.');
}
let _adminRejectTarget = null;
function openAdminRejectModal(type, id){
  _adminRejectTarget = {type, id};
  document.getElementById('adminReasonTitle').textContent = type==='identity' ? 'Reject identity verification' : 'Reject product listing';
  document.getElementById('adminReasonText').value = '';
  document.getElementById('adminReasonModal').classList.add('open');
}
function closeAdminReasonModal(){ document.getElementById('adminReasonModal').classList.remove('open'); _adminRejectTarget=null; }
function confirmAdminReject(){
  if(!_adminRejectTarget) return;
  const reason = document.getElementById('adminReasonText').value.trim() || 'No reason given.';
  if(_adminRejectTarget.type==='identity'){
    const phone = _adminRejectTarget.id;
    const acc = ACCOUNTS[phone];
    if(acc){
      acc.verification.status='unverified'; acc.verification.step=1; acc.verification.rejectionReason=reason;
      acc.verification.files = {idFront:false, idBack:false, selfie:false, documents:false};
      if(state.phone===phone){ renderVerification(); renderProfile(); }
    }
    pushNotification(phone, 'verification', `Your farmer verification was rejected: ${reason}. Please resubmit.`, null);
  }else{
    const p = PRODUCTS.find(x=>x.id===_adminRejectTarget.id);
    if(p){
      p.status='rejected'; p.rejectionReason=reason;
      pushNotification(p.farmerId, 'verification', `Your listing "${p.name}" was rejected: ${reason}`, null);
      renderListings(); renderMarketplace(); renderHomePanel(); renderTicker();
    }
  }
  closeAdminReasonModal();
  renderAdminDashboard();
  toast('Rejected.');
}

/* ===================== NEW LISTING (farmer posts a product) ===================== */
function openListingForm(){
  if(!state.loggedIn || state.role!=='farmer'){ toast('Log in as a farmer to list a product.'); go('login'); return; }
  document.getElementById('listingModalSub').textContent = "Add produce to the marketplace. Your listing will be saved for review before it goes live.";
  document.getElementById('ln-name').value='';
  document.getElementById('ln-unit').innerHTML = MEASURING_UNITS.map(u=>`<option value="${u}">${unitLabel(u)}</option>`).join('');
  document.getElementById('ln-price').value='';
  document.getElementById('ln-desc').value='';
  state.listingDraftImage=null;
  document.getElementById('listingThumbPicker').innerHTML = `<input type="file" accept="image/*" class="vh" id="listingImageInput" onchange="handleListingImageUpload(event)">` + thumbHTML(null,'#F1F5EA',true,'Add product photo');
  document.getElementById('listingModal').classList.add('open');
}
function closeListingForm(){ document.getElementById('listingModal').classList.remove('open'); }
function handleListingImageUpload(e){
  const file = e.target.files[0]; if(!file) return;
  readFileAsDataURL(file, url=>{
    state.listingDraftImage = url;
    document.getElementById('listingThumbPicker').innerHTML = `<input type="file" accept="image/*" class="vh" id="listingImageInput" onchange="handleListingImageUpload(event)">` + thumbHTML(url,'#F1F5EA',true,'Add product photo');
  });
}
async function submitListing(){
  const name = document.getElementById('ln-name').value.trim();
  const category = document.getElementById('ln-category').value;
  const unit = document.getElementById('ln-unit').value.trim();
  const price = Number(document.getElementById('ln-price').value);
  const desc = document.getElementById('ln-desc').value.trim();
  if(!name || !unit || !price){ toast('Fill in the product name, unit, and price.'); return; }
  ensureMyFarmerRecord();
  const palette = ['#F4D9CE','#EBD9E8','#F2E7B8','#F5E7B0','#E8DCC8','#F2ECD8','#E4D3C6','#EFE1CC'];
  try {
    const currentUser = await apiFetch('/me');
    if(currentUser.role !== 'farmer') { toast('Only farmer accounts can save products.'); return; }
    state.backendUserId = currentUser.id;
    localStorage.setItem('theraprice_backend_user_id', currentUser.id);
    const saved = await apiFetch('/products', {method:'POST', body:JSON.stringify({
      title:name, category, unit, price_xaf:price, description:desc || `${name}, listed by ${state.name}.`, image_url:state.listingDraftImage
    })});
    PRODUCTS.push({
      id: Date.now(), backendId:saved.id, name:saved.title, category:saved.category, color: palette[Math.floor(Math.random()*palette.length)], image:saved.image_url,
      price:saved.price_xaf, unit:saved.unit, farmerId:saved.farmer_id, status:'pending', rejectionReason:null, trend:'flat', prob:0, tier:'low', range:null, mid:null,
      desc:saved.description || '', why:{supply:'New listing — not enough history yet', season:'To be determined', weather:'To be determined', demand:'To be determined'}
    });
  } catch(error) { toast('Could not save product: '+error.message); return; }
  /* PRODUCTS.push({
    id: Date.now(), name, category, color: palette[Math.floor(Math.random()*palette.length)], image: state.listingDraftImage,
    price, unit, farmerId:state.phone, status:'pending', rejectionReason:null, trend:'flat', prob:0, tier:'low', range:null, mid:null,
    desc: desc || `${name}, listed by ${state.name}.`,
    why:{supply:'New listing — not enough history yet', season:'To be determined', weather:'To be determined', demand:'To be determined'}
  }); */
  closeListingForm();
  renderListings(); renderMarketplace(); renderHomePanel(); renderTicker();
  toast('Product submitted — an admin will review it before it goes live.');
}

/* ===================== BACKEND MARKETPLACE ===================== */
async function loadMarketplaceFromBackend(){
  try {
    const [listings, users, forecastCrops] = await Promise.all([apiFetch('/products'), apiFetch('/users'), apiFetch('/forecast/crops')]);
    FORECAST_CROPS = new Set((forecastCrops || []).map(c=>forecastCropKey(c.crop || c.commodity || c.name)));
    if(!Array.isArray(listings) || listings.length===0) return;

    FARMERS = users.filter(u=>u.role==='farmer').map(u=>({
      id:u.id, name:u.name, location:u.location || '', bio:'',
      verified:u.verification_status==='verified', avatar:null
    }));
    PRODUCTS = listings.map((item, index)=>({
      // The numeric id keeps the existing UI handlers compatible. backendId is
      // always used for orders, so the browser never invents a database id.
      id: index + 100000, backendId:item.id, name:item.title, category:item.category,
      color:'#F1F5EA', image:item.image_url, price:item.price_xaf, unit:item.unit,
      farmerId:item.farmer_id, status:item.verification_status==='verified' ? 'live' : 'pending',
      trend:item.prediction_direction || 'flat', prob:item.prediction_confidence || 0,
      tier:'low', range:null, mid:null, desc:item.description || '', forecastAvailable:FORECAST_CROPS.has(forecastCropKey(item.crop_type)),
      why:{supply:'Live market listing', season:'See forecast', weather:'See forecast', demand:'See forecast'}
    }));
    renderFilters(); renderMarketplace(); renderHomePanel(); renderTicker();
  } catch(error) {
    console.warn('Backend marketplace unavailable; demo listings remain visible.', error);
  }
}

/* ===================== INIT ===================== */
function init(){
  const savedPhone = localStorage.getItem('theraprice_logged_in_phone');
  if (savedPhone && ACCOUNTS[savedPhone]) {
    state.phone = savedPhone;
    state.backendUserId = localStorage.getItem('theraprice_backend_user_id');
    applyIdentity(ACCOUNTS[savedPhone]);
    state.loggedIn = true;
  }
  applyLanguage();
  renderTicker();
  renderHomePanel();
  renderAuthArea();
  renderFilters();
  renderMarketplace();
  loadMarketplaceFromBackend();
  document.getElementById('su-region').innerHTML = locationRegionOptions();
  document.getElementById('su-city').innerHTML = locationCityOptions(LOCATIONS[0].region);
  document.querySelector('nav.primary a[data-view="home"]').classList.add('active');
  document.getElementById('alertModal').addEventListener('click', e=>{ if(e.target.id==='alertModal') closeAlertModal(); });
  document.getElementById('listingModal').addEventListener('click', e=>{ if(e.target.id==='listingModal') closeListingForm(); });
  document.getElementById('cropModal').addEventListener('click', e=>{ if(e.target.id==='cropModal') cancelCrop(); });
  document.addEventListener('keydown', e=>{ if(e.key==='Escape'){ closeAlertModal(); closeListingForm(); } });
  const cropImg = document.getElementById('cropImg');
  cropImg.addEventListener('mousedown', cropPointerDown);
  cropImg.addEventListener('touchstart', cropPointerDown, {passive:true});
  document.addEventListener('mousemove', cropPointerMove);
  document.addEventListener('touchmove', cropPointerMove, {passive:false});
  document.addEventListener('mouseup', cropPointerUp);
  document.addEventListener('touchend', cropPointerUp);
}
init();
